insert into public.kb_entries (slug, topic, title, body, tags, source, status) values
  ($kb$site-overview$kb$, $kb$Overview$kb$, $kb$What the ITCAN corporate site is$kb$, $kb$Single-page marketing site for ITCAN Pte Ltd that replaces the WordPress site at itcan.biz. Built on the Relay motion system: preloader, a page-long three.js particle stream, spring physics, a red statement plate with a logo iris, and a cursor ring. ITCAN red #E5222E and blue replace the template colours. Live preview: https://relay-site-production.up.railway.app (not yet on itcan.biz). Repo: manishkrsg-cloud/itcan-site, folder relay/. Hosting: Railway project 'ITCAN CORP WEBSITE DEMO', service relay-site, environment production.$kb$, array['overview', 'hosting', 'repo']::text[], $kb$relay/docs/PROJECT.md$kb$, $kb$current$kb$),
  ($kb$sections-map$kb$, $kb$Overview$kb$, $kb$Section order and URL anchors$kb$, $kb$Top to bottom: Hero with service card carousel (#top), Practices (9, #integrations), Services (4 rows, #product), Sectors (10, #sectors), Statement plate (#statement), Offices (6, globe and live time zones, #scale), Awards (28, dashboard and coverflow, #signals), Numbers and testimonials (#proof), About (#about), Careers (#careers), Media (#media), Ways to engage (#pricing), Contact (#contact), Footer. Legal pages: /terms-of-use/, /privacy-policy/, /disclaimer/. Nav labels differ from anchors: Practices=#integrations, Services=#product, Offices=#scale, Awards=#signals, Numbers=#proof, Teams=#pricing.$kb$, array['sections', 'anchors', 'navigation']::text[], $kb$web/html/nav.html$kb$, $kb$current$kb$),
  ($kb$static-server$kb$, $kb$Architecture$kb$, $kb$server.js: zero-dependency static server$kb$, $kb$Node 20, no runtime dependencies. Serves relay/public, GET and HEAD only (405 otherwise). Brotli q11 or gzip 9 for text over 1KB, cached in memory per file and mtime. Cache: hashed chunks and ?v= assets 1 year immutable; HTML/CSS/JS/JSON no-cache with ETag; /assets/ 7 days. Byte ranges for video (Safari). Legacy WordPress paths 301 to section anchors. /healthz returns ok. Award photos missing at build 302 to www.itcan.biz/wp-content/uploads.$kb$, array['server', 'caching', 'redirects']::text[], $kb$relay/server.js$kb$, $kb$current$kb$),
  ($kb$build-pipeline$kb$, $kb$Architecture$kb$, $kb$Front-end build: web/ to public/$kb$, $kb$web/build.mjs stitches web/html partials with <!--#include name--> into public/index.html, bundles web/css/index.css into public/css/site.css and web/src/main.js into public/js (ESM, code-split; the WebGL stream is a lazy hashed chunk) with esbuild. Stamps ?v=<build timestamp> on CSS and JS. Writes the three legal pages from one template. public/ is committed and is the deploy artefact; Railway does not run the front-end build.$kb$, array['build', 'esbuild', 'public']::text[], $kb$web/build.mjs$kb$, $kb$current$kb$),
  ($kb$photo-fetch-at-build$kb$, $kb$Architecture$kb$, $kb$Photos are downloaded during the Railway build$kb$, $kb$npm run build in relay/ runs fetch-awards.mjs (28 award photos) and fetch-services.mjs (generated photographs as webp, uses sharp if present). They are gitignored, so a local preview shows blank photo frames unless you run that build locally. If an award photo failed to download, server.js redirects to the original on itcan.biz; that fallback breaks once WordPress is retired.$kb$, array['build', 'photos', 'railway']::text[], $kb$fetch-awards.mjs, fetch-services.mjs$kb$, $kb$current$kb$),
  ($kb$motion-engine$kb$, $kb$Architecture$kb$, $kb$Motion: springs, Lenis, three.js stream$kb$, $kb$Own spring engine (web/src/core/engine.js), Lenis smooth scroll, three.js particle stream with bloom (lazy chunk). prefers-reduced-motion: no preloader, no WebGL loop, springs land at once. Crawlers and lab tools get no preloader and no WebGL (src/gate.js). Add ?nogl to skip the stream for screenshots and tests. If WebGL cannot start, the stream fails quietly and the page still works.$kb$, array['motion', 'webgl', 'accessibility']::text[], $kb$web/src$kb$, $kb$current$kb$),
  ($kb$layout-frames$kb$, $kb$Architecture$kb$, $kb$Four layout frames and the --u unit$kb$, $kb$Breakpoint frames 1440 (desktop), 1200, 900 (tablet) and 580 (phone), set as custom properties in web/css/base.css (--page-width, --page-inset, type scale). Many art panels are absolutely positioned in a --u unit scaled to the frame, so overlaps are fixed by adjusting top/left in calc(N * var(--u)). Phone overrides live in each section's CSS and in web/css/mobile.css.$kb$, array['layout', 'responsive', 'css']::text[], $kb$web/css/base.css$kb$, $kb$current$kb$),
  ($kb$themes$kb$, $kb$Architecture$kb$, $kb$Light and dark themes$kb$, $kb$Dark by default. Light sets data-theme="light" on <html>, remembered in localStorage itcan-theme. initTheme() in src/ui.js binds every [data-theme-toggle], so the header button and the phone menu's Light theme row both work. Legal pages read the saved theme before first paint from /js/theme.js (no inline script under the CSP).$kb$, array['theme', 'dark-mode']::text[], $kb$web/src/ui.js$kb$, $kb$current$kb$),
  ($kb$rule-rebuild-public$kb$, $kb$Rules$kb$, $kb$Always rebuild and commit public/ with any web/ change$kb$, $kb$Railway serves public/ as committed. After editing web/, run npm run build in web/ and commit the regenerated public/ files (index.html, css/site.css, js/, legal pages) in the same commit.$kb$, array['build', 'deploy']::text[], $kb$README.md$kb$, $kb$current$kb$),
  ($kb$rule-no-inline-script$kb$, $kb$Rules$kb$, $kb$No inline script: the CSP blocks it$kb$, $kb$script-src is 'self' only. Any new script must be a file under public/js/. Inline style attributes are allowed (style-src 'unsafe-inline') because the motion engine writes inline styles.$kb$, array['security', 'csp']::text[], $kb$relay/server.js$kb$, $kb$current$kb$),
  ($kb$rule-new-origin-csp$kb$, $kb$Rules$kb$, $kb$A new third-party origin needs a CSP entry and a SECURITY.md line$kb$, $kb$Allowed today: YouTube (youtube-nocookie.com, youtube.com frames), i.ytimg.com thumbnails, www.itcan.biz images. Adding analytics, fonts or embeds from anywhere else means updating the CSP in server.js and SECURITY.md, and, for tracking, a PDPA consent decision first.$kb$, array['security', 'csp', 'privacy']::text[], $kb$relay/docs/SECURITY.md$kb$, $kb$current$kb$),
  ($kb$rule-tap-targets-44$kb$, $kb$Rules$kb$, $kb$Phone tap targets are at least 44px$kb$, $kb$Chips, maps buttons, footer icons, filter tabs and the tel:/mailto: links in office cards have a 2.75rem minimum height on phones. New buttons on phones follow the same floor.$kb$, array['mobile', 'accessibility']::text[], $kb$web/css/mobile.css$kb$, $kb$current$kb$),
  ($kb$rule-title-tracking-em$kb$, $kb$Rules$kb$, $kb$Heading letter-spacing is in em, never fixed rem$kb$, $kb$--letter-spacing-title is -0.045em (desktop), -0.03em at 900px and below, -0.025em at 580px and below. A fixed -0.125rem made phone headings run words together. Use em for any new heading tracking.$kb$, array['typography', 'mobile']::text[], $kb$web/css/base.css$kb$, $kb$current$kb$),
  ($kb$rule-page-margins$kb$, $kb$Rules$kb$, $kb$Cards sit on the 20px phone page margins$kb$, $kb$On phones every card spans the page width minus 20px each side, including the hero coverflow card (spectra.js sizes it as width - 40). Section heads are left-aligned on phones to match the cards.$kb$, array['mobile', 'layout']::text[], $kb$web/css/mobile.css$kb$, $kb$current$kb$),
  ($kb$rule-nav-no-transform$kb$, $kb$Rules$kb$, $kb$Never give .nav a transform or filter$kb$, $kb$On phones .nav-actions (Talk to us + menu) is position: fixed at the bottom of the viewport. A transform, filter or backdrop-filter on .nav or .nav-row would make it fixed to the header instead and break the dock. The blur lives on the sibling .nav-plate.$kb$, array['mobile', 'navigation', 'css']::text[], $kb$web/css/mobile.css$kb$, $kb$current$kb$),
  ($kb$rule-no-secrets$kb$, $kb$Rules$kb$, $kb$Never commit secrets$kb$, $kb$Do not commit .env, film/urls.env (presigned upload URLs) or Railway tokens. Deploy tokens live in ITCAN-Hub/deploy/.env on MK's machine only.$kb$, array['security', 'secrets']::text[], $kb$relay/docs/SECURITY.md$kb$, $kb$current$kb$),
  ($kb$rule-mailto-forms$kb$, $kb$Rules$kb$, $kb$Forms are mailto: nothing personal reaches the server$kb$, $kb$The brief form and footer call-back open the visitor's email app, routed to sales, jobs or info. Adding a server-side form needs input validation, rate limiting, CSRF protection, spam control and a PDPA review first.$kb$, array['forms', 'privacy', 'pdpa']::text[], $kb$relay/docs/PRD.md$kb$, $kb$current$kb$),
  ($kb$deploy-push$kb$, $kb$Operations$kb$, $kb$Normal deploy: push to main$kb$, $kb$Railway service relay-site builds from GitHub manishkrsg-cloud/itcan-site, branch main, root directory /relay, build npm run build, start npm start, health check /healthz, restart on failure (5 retries).$kb$, array['deploy', 'railway', 'github']::text[], $kb$railway.json$kb$, $kb$current$kb$),
  ($kb$deploy-cli-fallback$kb$, $kb$Operations$kb$, $kb$Fallback deploy: railway up with the project token$kb$, $kb$When a push is blocked: from the repo root run env -u RAILWAY_API_TOKEN RAILWAY_TOKEN=$RAILWAY_TOKEN_RELAY_SITE railway up --service relay-site --detach (token in ITCAN-Hub/deploy/.env). The service's /relay root directory applies to the upload. Then push the same commit so the repo and the live site match; otherwise the next push rolls the site back.$kb$, array['deploy', 'railway', 'cli']::text[], $kb$relay/docs/TRD.md$kb$, $kb$current$kb$),
  ($kb$preview-local$kb$, $kb$Operations$kb$, $kb$Local preview$kb$, $kb$cd relay/web && npm install && npm run build, then from relay/: PORT=4173 npm start and open http://localhost:4173 (add ?nogl to skip WebGL). Check phones at 390x844 and desktop at 1440x900, in both themes.$kb$, array['preview', 'testing']::text[], $kb$relay/docs/PROJECT.md$kb$, $kb$current$kb$),
  ($kb$verify-after-deploy$kb$, $kb$Operations$kb$, $kb$Checks after every deploy$kb$, $kb$/healthz returns 200; the served css/site.css?v= stamp matches the build; a phone screenshot pass shows no horizontal scroll (scrollWidth equals innerWidth), the dock and menu work, and the theme toggles.$kb$, array['deploy', 'testing', 'qa']::text[], $kb$relay/docs/TRD.md$kb$, $kb$current$kb$),
  ($kb$sync-working-copy$kb$, $kb$Operations$kb$, $kb$Working copy vs the git clone$kb$, $kb$MK edits in ~/Documents/Claude/Projects/itcan-website, which mirrors relay/ in the git clone ~/Documents/itcan-site. Before copying files across: git pull --ff-only in the clone and diff relay/ against the working copy so newer remote work is never overwritten (the clone was once 40 commits behind).$kb$, array['workflow', 'git']::text[], $kb$session 1 Oct 2026$kb$, $kb$current$kb$),
  ($kb$audiences-goals$kb$, $kb$Product$kb$, $kb$Audiences and goals$kb$, $kb$Audiences: enterprise buyers in SG, MY, AU, HK, IN, ID (send a brief); hiring managers needing contract talent (build a team); candidates (send CV to jobs@itcan.biz); press and partners (media@itcan.biz). Goals: enquiries per 1,000 visits (+25% after a baseline month), proof within two scrolls of the hero, mobile Lighthouse accessibility >= 95, LCP < 2.5s on 4G, all old WordPress URLs 301 to the right section.$kb$, array['product', 'goals', 'audiences']::text[], $kb$relay/docs/PRD.md$kb$, $kb$current$kb$),
  ($kb$content-facts$kb$, $kb$Product$kb$, $kb$Company facts used on the site$kb$, $kb$960 projects, 1,200+ employees, 480 clients, 6 offices (Singapore HQ at 30 Cecil Street, Prudential Tower #18-08; Kuala Lumpur; Sydney; Hong Kong; New Delhi; Jakarta), 28 awards 2007-2023 including ten Enterprise 50 wins, nine practices, ten sectors (confirmed by ITCAN Oct 2026). UEN 200413557M, MOM EA Licence 13C6429. Inboxes: info, sales, hr, jobs, media @itcan.biz; phone +65 6604 6805.$kb$, array['content', 'facts']::text[], $kb$README.md content map$kb$, $kb$current$kb$),
  ($kb$mobile-requirements$kb$, $kb$Product$kb$, $kb$Mobile requirements M-01 to M-11$kb$, $kb$No horizontal scroll from 360px; headings never touch; opaque header; phone header is logo only with Talk to us and menu in a bottom dock; 44px tap targets; section heads aligned with content; no text overlap at rest; 16px body and inputs; primary actions in thumb reach; phones get the same content and motion as desktop; cards on 20px margins. All met as of 1 Oct 2026 except award heat-map cells (26px).$kb$, array['mobile', 'requirements']::text[], $kb$relay/docs/PRD.md$kb$, $kb$current$kb$),
  ($kb$mobile-pass-2026-10-01$kb$, $kb$ui$kb$, $kb$Mobile UX pass, 1 Oct 2026 (commit 1f49685)$kb$, $kb$Heading tracking in em; phone titles 24 to 30px; header plate 90% opaque with blur; theme toggle moved into the menu; menu tiles numbered 01-11 instead of PR/SV codes; section heads left-aligned on phones; time-zone caption moved below the lanes; Open in maps never wraps; 44px tap targets; footer social text replaced by icons; statement title kept at its fitted phone size.$kb$, array['mobile', 'ui']::text[], $kb$commit 1f49685$kb$, $kb$current$kb$),
  ($kb$bottom-dock-2026-10-01$kb$, $kb$ui$kb$, $kb$Phone bottom dock and upward menu (commit dc28452)$kb$, $kb$MK 1 Oct 2026: menu at the bottom. On phones .nav-actions is a floating pill fixed above the safe area (--dock-h 3.75rem) with Talk to us and the menu button; body gets matching bottom padding. The menu opens upward as a two-column sheet (descriptions hidden) with the Light theme row. The header shows only the logo. Desktop unchanged.$kb$, array['mobile', 'navigation', 'ui']::text[], $kb$commit dc28452$kb$, $kb$current$kb$),
  ($kb$sectors-phone-spread-2026-10-01$kb$, $kb$ui$kb$, $kb$Sectors stack-to-spread animation on phones (commit dc28452)$kb$, $kb$MK 1 Oct 2026: the 10 sectors did not animate on mobile. sectors.js now runs the spread when (max-width: 580px) and (min-height: 600px) using the LP layout: 3+2 cards above the heading and 2+3 below. The band excludes the dock height (--ss-bot). Heading centred, subtitle hidden in spread mode, names 12px with hyphenation (Telecom&shy;munications). Tablets 581-1000px keep the static grid.$kb$, array['mobile', 'animation', 'sectors']::text[], $kb$commit dc28452$kb$, $kb$current$kb$),
  ($kb$statement-trigger-2026-10-01$kb$, $kb$ui$kb$, $kb$Statement text starts at 80% iris open$kb$, $kb$The statement plate's words used to wait until the iris was fully open, leaving an empty red card for about a second. wrap.dataset.open now flips at openEnd - 0.2 * OPEN * k (transitions.js). 0.45 was tried and showed words clipped by the iris. The clipped headline and the flying i mark mid-scroll are intended choreography, not bugs.$kb$, array['animation', 'statement']::text[], $kb$commit dc28452$kb$, $kb$current$kb$),
  ($kb$awards-chart-phones-2026-10-01$kb$, $kb$ui$kb$, $kb$Awards over time chart restored on phones$kb$, $kb$The wg-curves tile was display:none at 580px and below. It is back as a fifth tile (grid area c) with the curves and legend repositioned. Award filter chips are left-aligned on phones.$kb$, array['mobile', 'awards']::text[], $kb$commit dc28452$kb$, $kb$current$kb$),
  ($kb$phone-design-pass-2026-10-02$kb$, $kb$ui$kb$, $kb$Phone design pass: swipe rows, fewer labels, shorter page$kb$, $kb$MK 2 Oct 2026: mobile layout still needed proper design. Reviewed with ui-ux-pro-max and taste-skill. On phones (580px and below) the offices grid, the engage plans and the proof number/quote columns are horizontal scroll-snap rows (cards 86% wide, next card peeking, scrollbar hidden). Section badges hidden except the hero chip and sectors; services row numbers and Step N prefixes hidden; en-dashes replaced with hyphens; office coordinates hidden in the swipe cards. Page went from 30.4 to about 25 screens. Desktop unchanged.$kb$, array['mobile', 'ui', 'carousel']::text[], $kb$web/css/mobile.css$kb$, $kb$current$kb$),
  ($kb$security-headers$kb$, $kb$Security$kb$, $kb$Security headers on every response$kb$, $kb$CSP (self scripts, YouTube frames, itcan.biz and ytimg images, form-action self and mailto, frame-ancestors self), HSTS 1 year with includeSubDomains, X-Frame-Options SAMEORIGIN, nosniff, strict-origin-when-cross-origin referrer, Permissions-Policy camera/mic/geolocation off, COOP same-origin. Since 1 Oct 2026 also on /healthz, the award 302 and 500 responses. Path check requires ROOT + path.sep.$kb$, array['security', 'headers', 'csp']::text[], $kb$relay/docs/SECURITY.md$kb$, $kb$current$kb$),
  ($kb$deploy-credentials-risk$kb$, $kb$Security$kb$, $kb$Deploy tokens stored in plain text$kb$, $kb$ITCAN-Hub/deploy/.env holds a Railway workspace token (reaches every itcanbiz project) and the relay-site project token. Keep the file out of repos and backup sync; prefer the project token; rotate both if the machine is shared or lost.$kb$, array['security', 'secrets', 'railway']::text[], $kb$relay/docs/SECURITY.md$kb$, $kb$current$kb$),
  ($kb$open-git-push-403$kb$, $kb$Open items$kb$, $kb$git push to itcan-site returns 403$kb$, $kb$Since 1 Oct 2026 the local GitHub credentials cannot push to manishkrsg-cloud/itcan-site. Three commits (1f49685 mobile pass, 9560f93 docs, dc28452 dock and sectors) were deployed by CLI upload and exist only in ~/Documents/itcan-site. Fix access, then git push. P1: any other push rolls the live site back.$kb$, array['deploy', 'github', 'blocker']::text[], $kb$ISSUES.md ISS-01$kb$, $kb$open$kb$),
  ($kb$open-desktop-nav$kb$, $kb$Open items$kb$, $kb$Desktop nav is crowded$kb$, $kb$10 links plus a status pill and two buttons. Proposed: fold Numbers into Awards and Teams into Contact, or move them to the footer.$kb$, array['navigation', 'desktop']::text[], $kb$ISSUES.md ISS-06$kb$, $kb$open$kb$),
  ($kb$open-award-cells$kb$, $kb$Open items$kb$, $kb$Award heat-map cells are 26px on phones$kb$, $kb$Below the 44px tap target. Make them non-interactive on phones or enlarge the hit area.$kb$, array['mobile', 'awards', 'accessibility']::text[], $kb$ISSUES.md ISS-07$kb$, $kb$open$kb$),
  ($kb$open-small-labels$kb$, $kb$Open items$kb$, $kb$Some labels are 11px$kb$, $kb$.pr-name on phones and small mono captions. Raise to a 12px floor.$kb$, array['typography']::text[], $kb$ISSUES.md ISS-08$kb$, $kb$open$kb$),
  ($kb$open-visual-polish$kb$, $kb$Open items$kb$, $kb$Gradient heading fill and pure black background$kb$, $kb$Flagged by the taste review: use a solid heading colour and an off-black ground such as #05060a instead of #000.$kb$, array['visual', 'polish']::text[], $kb$ISSUES.md ISS-09$kb$, $kb$open$kb$),
  ($kb$open-no-tests$kb$, $kb$Open items$kb$, $kb$No automated checks$kb$, $kb$Add a Playwright smoke test (no horizontal scroll, menu, theme, no overlap at key anchors) and Lighthouse CI on mobile.$kb$, array['testing']::text[], $kb$ISSUES.md ISS-10$kb$, $kb$open$kb$),
  ($kb$open-privacy-review$kb$, $kb$Open items$kb$, $kb$Privacy policy not yet reviewed by ITCAN$kb$, $kb$The PDPA notice at /privacy-policy/ is new text. ITCAN must approve it before the itcan.biz cut-over.$kb$, array['privacy', 'pdpa', 'content']::text[], $kb$ISSUES.md ISS-11$kb$, $kb$open$kb$),
  ($kb$open-domain-cutover$kb$, $kb$Open items$kb$, $kb$Move from the Railway URL to itcan.biz$kb$, $kb$Release criteria: all P1 issues closed, privacy policy approved, Lighthouse mobile performance >= 80 and accessibility >= 95, redirects checked against the live WordPress sitemap. Then DNS, and consider HSTS preload.$kb$, array['launch', 'dns']::text[], $kb$PRD.md section 8$kb$, $kb$open$kb$),
  ($kb$history-relay-redesign$kb$, $kb$History$kb$, $kb$Relay redesign replaces WordPress itcan.biz$kb$, $kb$The site was rebuilt on the Relay template's motion system with ITCAN content from itcan.biz (home, services, about, careers, contact). Old WordPress paths (/services, /about-us, /contact-us, /career, /press, /our-offices and others) redirect 301 to section anchors to keep search ranking.$kb$, array['history', 'redesign', 'seo']::text[], $kb$README.md$kb$, $kb$current$kb$),
  ($kb$history-design-audit-2026-10-01$kb$, $kb$History$kb$, $kb$Design audit, 1 Oct 2026$kb$, $kb$Audit with ui-ux-pro-max and taste-skill at 1440px and 390px in both themes. Found: phone headings running together, see-through header, crowded phone header, two-letter menu icons, centred heads over left-aligned cards, a time-zone caption overlap, wrapping maps buttons, small tap targets, text social links, empty statement plate, low-contrast service steps, no sector animation on phones, a hidden awards chart. All fixed and deployed the same day except the open items.$kb$, array['history', 'audit', 'design']::text[], $kb$relay/docs/ISSUES.md$kb$, $kb$current$kb$)
